<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import type {Catalog,Plan} from '../../shared/schema';
import type {ValueQuote} from '../../shared/value';
import {t,td,dateLocale} from '../i18n';
const props=defineProps<{items:ValueQuote[];plan:Plan|null;catalog:Catalog;method:boolean}>();
const emit=defineEmits<{close:[];compare:[ValueQuote]}>();
const dialog=ref<HTMLDialogElement|null>(null),active=ref('overview');
const plan=computed(()=>props.items[0]?.plan??props.plan);
const evidence=computed(()=>{const ids=props.items.length?props.items.flatMap(q=>q.evidenceIds):plan.value?.freshness.evidenceIds??[];return [...props.catalog.evidence.filter(e=>ids.includes(e.id))].sort((a,b)=>b.fetchedAt.localeCompare(a.fetchedAt)).filter((e,i,all)=>all.findIndex(x=>x.url===e.url)===i).slice(0,3);});
const previous=document.activeElement as HTMLElement|null;
onMounted(()=>{dialog.value?.showModal();document.body.style.overflow='hidden';});
onBeforeUnmount(()=>{document.body.style.overflow='';previous?.focus();});
const hostname=(s:string)=>new URL(s).hostname;
const date=(s:string)=>new Date(s).toLocaleString(dateLocale(),{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const tabs:[string,'tabs.overview'|'tabs.sources'][]=[['overview','tabs.overview'],['sources','tabs.sources']];
</script>
<template><dialog ref="dialog" class="value-dialog" :class="{'compare-dialog':items.length>1}" aria-labelledby="dialog-title" @cancel.prevent="emit('close')" @click="e=>{if(e.target===dialog)emit('close')}"><div class="dialog-inner"><header class="dialog-heading"><div><p class="eyebrow">{{method?t('dialog.method'):items.length>1?t('dialog.compare'):td(plan?.product)}}</p><h2 id="dialog-title">{{method?t('dialog.methodTitle'):items.length>1?t('dialog.compareTitle'):td(plan?.name)}}</h2></div><button class="icon-button" :aria-label="t('dialog.close')" autofocus @click="emit('close')">×</button></header><template v-if="method"><div class="method-content"><div class="method-equation"><span>$1</span><span>→</span><strong>{{t('method.equivalent')}}</strong></div><p>{{t('method.p1')}}</p><div class="method-equation"><span>{{t('method.scoreLabel')}}</span><span>=</span><strong>{{t('method.scoreFormula')}}</strong></div><p>{{t('method.scoreNote')}}</p><h3>{{t('method.rulesTitle')}}</h3><ul><li>{{t('method.rule1')}}</li><li>{{t('method.rule2')}}</li><li>{{t('method.rule3')}}</li><li>{{t('method.rule4')}}</li><li>{{t('method.rule5')}}</li></ul><p class="context-note">{{t('method.footnote')}}</p></div></template><template v-else><nav v-if="items.length<=1" class="dialog-tabs" :aria-label="t('tabs.planInfo')"><button v-for="[id,key] in tabs" :key="id" :class="{active:active===id}" @click="active=id">{{t(key)}}</button></nav><div v-if="active==='sources'" class="source-cards"><article v-for="e in evidence" :key="e.id"><a :href="e.url" target="_blank" rel="noopener noreferrer">{{e.title}} ↗</a><p>{{e.publisher}} · {{e.method==='user-import'?t('sources.userImport'):t('sources.fetched')}} {{date(e.fetchedAt)}}</p><small>{{hostname(e.url)}}</small></article><p class="context-note">{{t('sources.note')}}</p></div><template v-else><div v-if="items.length" class="quote-details" :style="{'--compare-count':items.length}"><section v-for="q in items" :key="q.id" class="quote-detail"><h3 v-if="items.length>1" class="compare-plan-name">{{td(q.plan.name)}}</h3><div class="dialog-ratio"><strong>{{q.multiplier.toFixed(1)}}<span>×</span></strong><div>{{t('detail.perDollar')}}<small>{{t('detail.apiEquivalent',{v:q.multiplier.toFixed(2)})}}</small></div></div><h3>{{q.model.name}} <span class="muted">· {{td(q.offer.label)}}</span></h3><dl class="detail-facts"><div><dt>{{q.plan.billing.interval==='year'?t('detail.monthlyAmortized'):t('detail.actualCost')}}</dt><dd>{{q.plan.billing.interval==='once'?`$${q.upfrontCost} · ${t('list.oneTime')}`:q.monthlyCost===null?t('detail.byUsage'):`$${q.monthlyCost.toLocaleString('en-US',{maximumFractionDigits:2})}${t('detail.perMonthSuffix')}`}}</dd></div><div v-if="q.plan.billing.interval==='year'"><dt>{{t('detail.annualUpfront')}}</dt><dd>${{q.upfrontCost.toLocaleString('en-US',{maximumFractionDigits:2})}}</dd></div><div><dt>{{t('detail.utilization')}}</dt><dd>{{q.offer.kind==='metered'?t('detail.usageBased'):t('detail.quotaPercent',{n:q.calculation.utilization*100})}}</dd></div><div><dt>{{t('detail.abilityRank')}}</dt><dd>{{q.benchmark?.rank?`#${q.benchmark.rank}`:'—'}}</dd></div><div><dt>{{t('detail.verifiedAt')}}</dt><dd>{{date(q.verifiedAt)}}</dd></div><div><dt>{{t('detail.validUntil')}}</dt><dd>{{date(q.validUntil)}}</dd></div></dl><ul class="conditions-list"><li v-for="line in [...new Set([...q.offer.conditions,...q.plan.limitations])]" :key="line">{{td(line)}}</li></ul><section v-if="q.research" class="research-notes"><p class="research-label">{{td(q.research.label)}} · {{t('research.originalCheck')}} {{date(q.research.originalCheckedAt)}}</p><p v-if="q.research.low!==null">{{t('research.range',{lo:q.research.low.toFixed(1),hi:q.research.high===null?'—':q.research.high.toFixed(1),c:td(q.research.confidence)})}}</p><p v-for="note in q.research.reviewNotes.slice(-1)" :key="note" class="shared-warning">{{td(note)}}</p><p>{{td(q.research.warning)}}</p><details><summary>{{t('research.sourcesWeights')}}</summary><article v-for="s in [...q.research.sourceSamples].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3)" :key="s.url" class="research-source"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{td(s.label)}} ↗</a><small>{{s.date}} · {{t('research.weight',{n:Math.round(s.weight*100)})}} · {{t('research.monthlyEquivalent',{v:s.value.toLocaleString()})}}</small><p>{{td(s.note)}}</p></article><p>{{td(q.research.method)}}</p></details></section><details v-else class="calculation-details"><summary>{{t('calc.basis')}}</summary><dl class="detail-facts"><div><dt>{{t('calc.paid')}}</dt><dd>${{q.calculation.cash.toFixed(2)}}</dd></div><div><dt>{{t('calc.usableQuota')}}</dt><dd>{{q.calculation.usableUnits.toLocaleString()}}</dd></div><div><dt>{{t('calc.totalTokens')}}</dt><dd>{{q.calculation.millionTokens?.toFixed(2)??'—'}} M</dd></div><div><dt>{{t('calc.apiEquivalent')}}</dt><dd>${{q.calculation.equivalentUSD.toFixed(2)}}</dd></div></dl><p>{{t('calc.sameMix',{cache:q.calculation.cachedInputShare?t('calc.cached'):t('calc.noCache'),window:q.offer.kind==='allowance'?t('calc.windowLimit'):''})}}</p></details><div v-if="items.length===1" class="dialog-actions"><button class="outline-button" @click="emit('compare',q)">{{t('action.compare')}}</button><a class="solid-button" :href="q.plan.purchaseUrl" target="_blank" rel="noopener noreferrer">{{t('action.visitOfficial')}}</a></div></section></div><template v-else-if="plan"><p class="unknown-callout">{{t('unknown.callout')}}</p><p>{{td(plan.description)}}</p><dl class="detail-facts"><div><dt>{{t('unknown.listPrice')}}</dt><dd v-if="plan.billing.interval==='usage'">{{t('detail.byUsage')}}</dd><dd v-else>${{plan.billing.amount}} / {{plan.billing.interval==='once'?t('list.oneTime'):plan.billing.interval==='year'?t('unknown.perYear'):t('unknown.perMonth')}}</dd></div><div v-if="plan.apiRates"><dt>{{t('detail.apiInputRate')}}</dt><dd>${{plan.apiRates.inputPerMillion}}</dd></div><div v-if="plan.apiRates"><dt>{{t('detail.apiOutputRate')}}</dt><dd>${{plan.apiRates.outputPerMillion}}</dd></div><div><dt>{{t('unknown.quotaNotes')}}</dt><dd>{{td(plan.quota.notes)}}</dd></div><div><dt>{{t('detail.verifiedAt')}}</dt><dd>{{date(plan.freshness.verifiedAt)}}</dd></div></dl><ul class="conditions-list"><li v-for="line in [...plan.benefits,...plan.limitations]" :key="line">{{td(line)}}</li></ul><a class="solid-button" :href="plan.purchaseUrl" target="_blank" rel="noopener noreferrer">{{t('action.visitOfficial')}}</a></template><p v-if="items.length>1&&items.some(q=>q.offer.sharedGroup&&items.filter(x=>x.offer.sharedGroup===q.offer.sharedGroup).length>1)" class="shared-warning">{{t('dialog.sharedWarning')}}</p></template></template></div></dialog></template>
